<div><div style="display:flex;justify-content:space-between;align-items:center"><div><p class="eyebrow">CLIENT DIRECTORY</p><h2>Manage users</h2></div><a class="button" href="<?=base_url('admin/users/create')?>">Create new user</a></div><?php if($this->session->flashdata('success')):?><p class="alert success"><?=$this->session->flashdata('success')?></p><?php endif;?><section class="panel"><table class="table"><tr><th>Customer</th><th>Email</th><th>Phone</th><th>Country</th><th>Status</th><th>Joined</th></tr><?php foreach($users as $user):?><tr><td><b><?=html_escape($user['first_name'].' '.$user['last_name'])?></b></td><td><?=html_escape($user['email'])?></td><td><?=html_escape($user['phone'])?></td><td><?=html_escape($user['country'])?></td><td><span class="badge <?=$user['status']?>"><?=$user['status']?></span></td><td><?=date('M j, Y',strtotime($user['created_at']))?></td></tr><?php endforeach;?></table></section></div>
